import { describe, expect, it } from 'vitest'
import { encodeMulticallExtended } from './multicallExtended'

describe('MulticallExtended', () => {
  it('works with no validation', () => {
    const calldata = encodeMulticallExtended('0x01')
    expect(calldata).toBe('0x01')
  })

  it('works with deadline as string', () => {
    const calldata = encodeMulticallExtended('0x01', '123')
    expect(calldata).toBe(
      ''
    )
  })

  it('works with deadline as number', () => {
    const calldata = encodeMulticallExtended('0x01', 123)
    expect(calldata).toBe(
      ''
    )
  })

  it('works with previous block hash', () => {
    const calldata = encodeMulticallExtended(
      '0x01',
      '0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'
    )
    expect(calldata).toBe(
      ''
    )
  })
})
